#include <stdio.h>

int main(void) {
    int bowls[8];
    int n, step;

    if (scanf("%d", &n) != 1) {
        return 1;
    }
    if (scanf("%d", &step) != 1) {
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    int *p = bowls;
    for (int i = 0; i < n; i = i + step) {
        printf("第 %d 只：%d\n", i, *p);
        p = p + step;
    }
    return 0;
}
